'use strict';
// Persistence of AI Mode conversations in the EXISTING AiChatSession collection
// (models/AiChatSession.js: workspaceId, sessionId, messages[], pendingAction),
// so the English page can still show the conversation and the two agents see one
// history. Nothing in that model changes; this file only reads and writes it.
//
// Every query is scoped by {sessionId, workspaceId} with workspaceId taken from
// the verified token. sessionId is UNIQUE across all workspaces in the existing
// schema (it is generated by the browser), so an id that belongs to another
// workspace is reported as SESSION_NOT_FOUND and is never read or written.
//
// What is persisted (brief B7a §5): the merchant's text and the final reply (or
// the deterministic confirmation text) only. The pendingAction sub-document is
// strict: it keeps exactly id / toolName / args / summary / createdAt.
//
// Writes are atomic single-document operations ($push / conditional $set), not
// load-modify-save, for two reasons. A second tab or a retry must not overwrite a
// reply that was saved in between. And the pending-action CLAIM below must be
// one conditional update so that of two simultaneous confirms exactly one wins
// (agent.js, gate rule 3).
//
// The model is injectable (tests pass a fake); the default requires it lazily.
const { withWorkspace } = require('../scope');

function coded(status, code, message) {
  const err = new Error(message);
  err.status = status;
  err.code = code;
  return err;
}

const notFound = () => coded(404, 'SESSION_NOT_FOUND', 'Session not found');

function assertText(value, label) {
  if (typeof value !== 'string' || !value) throw coded(400, 'INVALID_INPUT', `${label} must be a non-empty string`);
  return value;
}

function toMessage(m) {
  return { role: m.role, text: m.text, createdAt: m.createdAt };
}

function toPending(p) {
  if (!p || typeof p !== 'object' || !p.id) return null;
  return { id: p.id, toolName: p.toolName, args: p.args, summary: p.summary, createdAt: p.createdAt };
}

function createMongoSessionStore({ Model } = {}) {
  let model = Model || null;
  const M = () => model || (model = require('../../../models/AiChatSession'));

  // withWorkspace throws when workspaceId is missing: a store call is never unscoped.
  const scope = (sessionId, workspaceId) => withWorkspace({ sessionId: assertText(sessionId, 'sessionId') }, workspaceId);

  async function find(sessionId, workspaceId) {
    const doc = await M().findOne(scope(sessionId, workspaceId)).lean();
    if (!doc) return null;
    return {
      sessionId: doc.sessionId,
      workspaceId: String(workspaceId),
      messages: (doc.messages || []).map(toMessage),
      pendingAction: toPending(doc.pendingAction),
    };
  }

  // An existing session of this workspace, or a new in-memory one (created in the
  // database by the first saveTurn). 404 when the id is taken by another workspace.
  async function findOrCreate(sessionId, workspaceId) {
    const existing = await find(sessionId, workspaceId);
    if (existing) return existing;
    if (await M().exists({ sessionId })) throw notFound();
    return { sessionId, workspaceId: String(workspaceId), messages: [], pendingAction: null };
  }

  // Append the turn's messages and set (or clear) the pending action in one
  // atomic update; creates the session if this is its first turn.
  async function saveTurn({ sessionId, workspaceId, messages, pendingAction }) {
    const filter = scope(sessionId, workspaceId);
    const update = {
      $push: { messages: { $each: (messages || []).map(toMessage) } },
      $set: { pendingAction: toPending(pendingAction) },
    };
    try {
      await M().updateOne(filter, update, { upsert: true });
    } catch (err) {
      if (!err || err.code !== 11000) throw err;
      // Duplicate key on the unique sessionId: two first messages raced (then the
      // document is ours now and one retry succeeds) or the id is another workspace's.
      if (!(await M().exists(filter))) throw notFound();
      await M().updateOne(filter, update, { upsert: true });
    }
  }

  // Atomically take the pending action: true for exactly one caller.
  async function claimPendingAction({ sessionId, workspaceId, actionId }) {
    if (typeof actionId !== 'string' || !actionId) return false;
    const result = await M().updateOne({ ...scope(sessionId, workspaceId), 'pendingAction.id': actionId }, { $set: { pendingAction: null } });
    return !!result && result.modifiedCount === 1;
  }

  async function appendMessages({ sessionId, workspaceId, messages }) {
    if (!messages || !messages.length) return;
    await M().updateOne(scope(sessionId, workspaceId), { $push: { messages: { $each: messages.map(toMessage) } } });
  }

  return { find, findOrCreate, saveTurn, claimPendingAction, appendMessages };
}

module.exports = { createMongoSessionStore, notFound };
